import datetime
import difflib
from typing import Dict, List, Optional

def detect_duplicate(movement: Dict, others: List[Dict]) -> Optional[Dict]:
    if not others:
        return None

    try:
        # Parsear fecha del movimiento actual
        m_date = datetime.date.fromisoformat(movement['transactionDate'])
    except (ValueError, TypeError, KeyError):
        return None

    DATE_WINDOW_DAYS = 1
    AMOUNT_EPSILON = 0.0001

    for other in others:
        try:
            # Parsear fecha del otro movimiento
            other_date = datetime.date.fromisoformat(other['transactionDate'])
        except (ValueError, TypeError, KeyError):
            continue

        # Verificar ventana de fechas
        if abs((m_date - other_date).days) > DATE_WINDOW_DAYS:
            continue

        # Verificar monto (creditos y debitos) con tolerancia
        credit_diff = abs(movement.get('creditAmount', 0) - other.get('creditAmount', 0))
        debit_diff = abs(movement.get('debitAmount', 0) - other.get('debitAmount', 0))

        if credit_diff > AMOUNT_EPSILON or debit_diff > AMOUNT_EPSILON:
            continue

        # Verificar referencia o descripción
        ref_match = movement.get('reference', '').strip() == other.get('reference', '').strip()
        desc_sim_score = difflib.SequenceMatcher(None, 
            movement.get('description', ''), 
            other.get('description', '')).ratio()

        is_desc_exact = movement.get('description', '') == other.get('description', '')

        # Determinar confianza y razón según el tipo de coincidencia
        if ref_match:
            return {
                'isDuplicate': True,
                'originalMovementId': other['id'],
                'confidence': 1.0,
                'reason': "Monto, fecha y referencia coinciden exactamente."
            }
        elif is_desc_exact:
            return {
                'isDuplicate': True,
                'originalMovementId': other['id'],
                'confidence': 0.95,
                'reason': "Monto, fecha y descripción coinciden exactamente."
            }
        elif desc_sim_score > 0.9:
            return {
                'isDuplicate': True,
                'originalMovementId': other['id'],
                'confidence': 0.9,
                'reason': "Monto, fecha y descripción tienen alta similitud."
            }
        elif desc_sim_score > 0.8:
            return {
                'isDuplicate': True,
                'originalMovementId': other['id'],
                'confidence': 0.75,
                'reason': "Monto y fecha coinciden con similitud en la descripción."
            }

    return None
