def application_decision(amount, open_invoices, balance):
    # No open invoices case
    if not open_invoices:
        if balance > 0:
            return {
                'type': 'balance_forward',
                'invoiceId': None,
                'details': f'Pago aplicado a saldo a favor por S/ {amount}'
            }
        else:
            return {
                'type': 'advance',
                'invoiceId': None,
                'details': f'Pago registrado como anticipo por S/ {amount}'
            }

    # Sort invoices by dueDate (oldest first)
    sorted_invoices = sorted(open_invoices, key=lambda x: x['dueDate'])

    remaining = amount
    paid_amount = 0

    for invoice in sorted_invoices:
        if remaining <= 0:
            break

        if remaining >= invoice['balance']:
            paid = invoice['balance']
        else:
            paid = remaining

        paid_amount += paid
        remaining -= paid

        if invoice['balance'] == paid:
            # Full coverage or partial but exact to invoice balance
            if paid == invoice['balance']:
                result = {
                    'type': 'full',
                    'invoiceId': invoice['id'],
                    'details': f'Pago cubierto completamente por factura ID {invoice["id"]}'
                }
            else:
                result = {
                    'type': 'partial',
                    'invoiceId': invoice['id'],
                    'details': f'Pago parcial aplicado a factura ID {invoice["id"]}'
                }
            return result
        else:
            # Partial coverage of invoice
            return {
                'type': 'partial',
                'invoiceId': invoice['id'],
                'details': f'Pago parcial aplicado a factura ID {invoice["id"]}'
            }
